import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_01_01_execution_stack.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_01_02_agent_loop.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_01_03_surfaces.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_01_04_cost.png",d="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_01_05_source_layers.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_01_06_delivery.png",q=JSON.parse('{"title":"Codex 到底是什么：从“会写代码”到“能完成任务”的官方全景图","description":"如果只把 Codex 理解成一个更聪明的代码补全工具，你会错过它真正的变化：模型不再只生成一段答案，而是进入一个受控执行环境，读取仓库、调用工具、修改文件、运行验证，再把差异和证据交还给人。OpenAI Docs 对 Codex 的核心定位，是能够代表开发者执行软件工程工作的编码代理，而不是脱离项目","frontmatter":{"title":"Codex 到底是什么：从“会写代码”到“能完成任务”的官方全景图","description":"如果只把 Codex 理解成一个更聪明的代码补全工具，你会错过它真正的变化：模型不再只生成一段答案，而是进入一个受控执行环境，读取仓库、调用工具、修改文件、运行验证，再把差异和证据交还给人。OpenAI Docs 对 Codex 的核心定位，是能够代表开发者执行软件工程工作的编码代理，而不是脱离项目","date":"2026-08-10","topic":"AI 底层学习","section":"OpenAI官方文档解读","readingTime":6,"source":"2026-08-10/ai_codex_official_01_overview.md","status":"archived","cover":"/article-assets/2026-08-10/ai_codex_official_01_01_execution_stack.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Codex 到底是什么：从“会写代码”到“能完成任务”的官方全景图"}],["meta",{"property":"og:description","content":"如果只把 Codex 理解成一个更聪明的代码补全工具，你会错过它真正的变化：模型不再只生成一段答案，而是进入一个受控执行环境，读取仓库、调用工具、修改文件、运行验证，再把差异和证据交还给人。OpenAI Docs 对 Codex 的核心定位，是能够代表开发者执行软件工程工作的编码代理，而不是脱离项目"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_01_01_execution_stack.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"Codex 到底是什么：从“会写代码”到“能完成任务”的官方全景图"}],["meta",{"name":"twitter:description","content":"如果只把 Codex 理解成一个更聪明的代码补全工具，你会错过它真正的变化：模型不再只生成一段答案，而是进入一个受控执行环境，读取仓库、调用工具、修改文件、运行验证，再把差异和证据交还给人。OpenAI Docs 对 Codex 的核心定位，是能够代表开发者执行软件工程工作的编码代理，而不是脱离项目"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_01_01_execution_stack.png"}],["meta",{"name":"robots","content":"noindex,follow"}]],"search":false,"prev":false,"next":false},"headers":[],"relativePath":"archive/ai-codex-official-01-overview.md","filePath":"archive/ai-codex-official-01-overview.md","lastUpdated":null}'),h={name:"archive/ai-codex-official-01-overview.md"};function p(_,e,x,u,f,m){return t(),o("div",null,[...e[0]||(e[0]=[i('<blockquote><p>本文为历史归档版本，不再更新。请阅读<a href="/Nav2ArticlesSite/ai/openai-codex-complete-guide">当前版本</a>。</p></blockquote><h1 id="codex-到底是什么-从-会写代码-到-能完成任务-的官方全景图" tabindex="-1">Codex 到底是什么：从“会写代码”到“能完成任务”的官方全景图 <a class="header-anchor" href="#codex-到底是什么-从-会写代码-到-能完成任务-的官方全景图" aria-label="Permalink to &quot;Codex 到底是什么：从“会写代码”到“能完成任务”的官方全景图&quot;">​</a></h1><p>如果只把 Codex 理解成一个更聪明的代码补全工具，你会错过它真正的变化：模型不再只生成一段答案，而是进入一个受控执行环境，读取仓库、调用工具、修改文件、运行验证，再把差异和证据交还给人。OpenAI Docs 对 Codex 的核心定位，是能够代表开发者执行软件工程工作的编码代理，而不是脱离项目现实的聊天框。</p><h2 id="一、codex-是由五层组成的执行系统" tabindex="-1">一、Codex 是由五层组成的执行系统 <a class="header-anchor" href="#一、codex-是由五层组成的执行系统" aria-label="Permalink to &quot;一、Codex 是由五层组成的执行系统&quot;">​</a></h2><h3 id="_1-1-模型负责理解与推理" tabindex="-1">1.1 模型负责理解与推理 <a class="header-anchor" href="#_1-1-模型负责理解与推理" aria-label="Permalink to &quot;1.1 模型负责理解与推理&quot;">​</a></h3><p>模型读取用户目标、项目说明、代码、日志和工具结果，判断下一步要做什么。它决定分析深度，却不直接等于完整的 Codex。只比较模型榜单，无法解释代理为什么能修改仓库，也无法解释它为什么会被沙箱拦住。</p><h3 id="_1-2-上下文负责提供项目现实" tabindex="-1">1.2 上下文负责提供项目现实 <a class="header-anchor" href="#_1-2-上下文负责提供项目现实" aria-label="Permalink to &quot;1.2 上下文负责提供项目现实&quot;">​</a></h3><p>当前文件、目录结构、<code>AGENTS.md</code>、配置、测试、错误日志和对话历史共同组成任务上下文。模型能力再强，如果工作目录错误、日志过期或规则冲突，得到的仍可能是逻辑完整但不适用于当前仓库的答案。</p><h3 id="_1-3-工具负责改变外部状态" tabindex="-1">1.3 工具负责改变外部状态 <a class="header-anchor" href="#_1-3-工具负责改变外部状态" aria-label="Permalink to &quot;1.3 工具负责改变外部状态&quot;">​</a></h3><p>搜索文件、读取源码、执行命令、编辑文件、浏览网页和调用 MCP 都属于工具层。工具把语言推理变成可观察动作，也是 Codex 与普通问答最明显的边界。</p><h3 id="_1-4-权限负责限制动作半径" tabindex="-1">1.4 权限负责限制动作半径 <a class="header-anchor" href="#_1-4-权限负责限制动作半径" aria-label="Permalink to &quot;1.4 权限负责限制动作半径&quot;">​</a></h3><p>沙箱决定命令技术上能碰到什么，审批决定跨越边界前由谁判断。代理不是因为“答应小心”才安全，而是因为运行时把文件、网络和外部动作限制在明确范围。</p><h3 id="_1-5-验证负责决定任务能否结束" tabindex="-1">1.5 验证负责决定任务能否结束 <a class="header-anchor" href="#_1-5-验证负责决定任务能否结束" aria-label="Permalink to &quot;1.5 验证负责决定任务能否结束&quot;">​</a></h3><p>Diff、测试、构建、静态检查、运行日志和人工 Review 是任务完成的证据。Codex 可以主动执行验证，但是否接受结果仍由开发者负责。</p><p><img src="'+r+'" alt="图 1：模型、上下文、工具、权限与验证组成 Codex 执行栈"></p><h2 id="二、agent-与聊天回答的差异在于闭环" tabindex="-1">二、Agent 与聊天回答的差异在于闭环 <a class="header-anchor" href="#二、agent-与聊天回答的差异在于闭环" aria-label="Permalink to &quot;二、Agent 与聊天回答的差异在于闭环&quot;">​</a></h2><h3 id="_2-1-聊天回答交付建议" tabindex="-1">2.1 聊天回答交付建议 <a class="header-anchor" href="#_2-1-聊天回答交付建议" aria-label="Permalink to &quot;2.1 聊天回答交付建议&quot;">​</a></h3><p>普通问答通常在生成文本后结束。用户需要自己复制代码、切换终端、处理报错并判断结果。它适合解释概念、讨论方案和生成局部示例。</p><h3 id="_2-2-编码代理交付状态变化" tabindex="-1">2.2 编码代理交付状态变化 <a class="header-anchor" href="#_2-2-编码代理交付状态变化" aria-label="Permalink to &quot;2.2 编码代理交付状态变化&quot;">​</a></h3><p>Codex 会持续观察工具结果并调整行动：搜索调用链、修改实现、运行测试、根据失败继续修正。这条观察、行动、验证、反馈的循环，才是 Agent 的核心。</p><h3 id="_2-3-人的职责从操作上移到决策" tabindex="-1">2.3 人的职责从操作上移到决策 <a class="header-anchor" href="#_2-3-人的职责从操作上移到决策" aria-label="Permalink to &quot;2.3 人的职责从操作上移到决策&quot;">​</a></h3><p>代理承担机械搜索和执行，人负责目标、架构取舍、风险授权与最终验收。AI 没有消除人的责任，只是把人的注意力从逐行操作上移到更高价值判断。</p><p><img src="'+c+'" alt="图 2：从自然语言目标到可验证状态变化的代理闭环"></p><h2 id="三、不同入口共享能力-但运行位置不同" tabindex="-1">三、不同入口共享能力，但运行位置不同 <a class="header-anchor" href="#三、不同入口共享能力-但运行位置不同" aria-label="Permalink to &quot;三、不同入口共享能力，但运行位置不同&quot;">​</a></h2><h3 id="_3-1-本地入口使用本机项目现实" tabindex="-1">3.1 本地入口使用本机项目现实 <a class="header-anchor" href="#_3-1-本地入口使用本机项目现实" aria-label="Permalink to &quot;3.1 本地入口使用本机项目现实&quot;">​</a></h3><p>ChatGPT 桌面端、Codex CLI 和 IDE 扩展可以在本机工作区执行任务。它们更容易使用尚未推送的修改、本地工具链和开发者当前环境，也因此必须尊重本机权限和未提交工作。</p><h3 id="_3-2-cloud-入口使用可重建远程环境" tabindex="-1">3.2 Cloud 入口使用可重建远程环境 <a class="header-anchor" href="#_3-2-cloud-入口使用可重建远程环境" aria-label="Permalink to &quot;3.2 Cloud 入口使用可重建远程环境&quot;">​</a></h3><p>Codex Cloud 从连接的代码仓库与环境配置重建任务现场。它适合长任务和并行工作，但不能自动看到本机未提交状态。环境脚本、依赖、Secrets 和网络规则必须显式配置。</p><h3 id="_3-3-入口选择取决于任务摩擦" tabindex="-1">3.3 入口选择取决于任务摩擦 <a class="header-anchor" href="#_3-3-入口选择取决于任务摩擦" aria-label="Permalink to &quot;3.3 入口选择取决于任务摩擦&quot;">​</a></h3><p>局部编辑适合 IDE，终端密集任务适合 CLI，可视化并行与 Review 适合桌面端，可独立重建的长任务适合 Cloud。入口不同，不代表需要学习四套完全独立的方法。</p><p><img src="'+l+'" alt="图 3：桌面端、CLI、IDE 与 Cloud 的执行位置"></p><h2 id="四、codex-不替开发者做最终判断" tabindex="-1">四、Codex 不替开发者做最终判断 <a class="header-anchor" href="#四、codex-不替开发者做最终判断" aria-label="Permalink to &quot;四、Codex 不替开发者做最终判断&quot;">​</a></h2><h3 id="_4-1-它不能保证结果绝对正确" tabindex="-1">4.1 它不能保证结果绝对正确 <a class="header-anchor" href="#_4-1-它不能保证结果绝对正确" aria-label="Permalink to &quot;4.1 它不能保证结果绝对正确&quot;">​</a></h3><p>模型可能误解业务、遗漏边界或编写只对当前样例成立的测试。代理能够运行命令，只能证明它执行了验证，不能证明验证覆盖了所有真实要求。</p><h3 id="_4-2-它不能猜出未表达的需求" tabindex="-1">4.2 它不能猜出未表达的需求 <a class="header-anchor" href="#_4-2-它不能猜出未表达的需求" aria-label="Permalink to &quot;4.2 它不能猜出未表达的需求&quot;">​</a></h3><p>业务规则、兼容承诺、性能预算和组织红线必须由人给出。未写明的信息只能被推断，越高风险的任务越不能依赖默认猜测。</p><h3 id="_4-3-它不能绕过真实权限系统" tabindex="-1">4.3 它不能绕过真实权限系统 <a class="header-anchor" href="#_4-3-它不能绕过真实权限系统" aria-label="Permalink to &quot;4.3 它不能绕过真实权限系统&quot;">​</a></h3><p>仓库、云环境、连接器和本地文件系统仍执行各自权限。ChatGPT Workspace 身份、GitHub 权限和 Platform API 凭据也不是同一套授权。</p><h2 id="五、成本来自计算与上下文" tabindex="-1">五、成本来自计算与上下文 <a class="header-anchor" href="#五、成本来自计算与上下文" aria-label="Permalink to &quot;五、成本来自计算与上下文&quot;">​</a></h2><h3 id="_5-1-订阅与-api-是不同计费边界" tabindex="-1">5.1 订阅与 API 是不同计费边界 <a class="header-anchor" href="#_5-1-订阅与-api-是不同计费边界" aria-label="Permalink to &quot;5.1 订阅与 API 是不同计费边界&quot;">​</a></h3><p>Codex 可以通过符合条件的 ChatGPT 方案使用，也可以在支持的程序化场景中使用 API 凭据。具体额度、模型和可用性变化较快，应实时查看官方 Pricing 页面，不在项目规范中永久写死。</p><h3 id="_5-2-无效上下文会制造隐性成本" tabindex="-1">5.2 无效上下文会制造隐性成本 <a class="header-anchor" href="#_5-2-无效上下文会制造隐性成本" aria-label="Permalink to &quot;5.2 无效上下文会制造隐性成本&quot;">​</a></h3><p>过大的日志、无关目录、重复对话和模糊目标会增加检索、推理与工具往返。真正的优化不是少写几个字，而是让每次计算都靠近可验收结果。</p><p><img src="'+n+'" alt="图 4：上下文、推理、工具往返与返工构成任务成本"></p><h2 id="六、官方文档应成为易变事实的来源" tabindex="-1">六、官方文档应成为易变事实的来源 <a class="header-anchor" href="#六、官方文档应成为易变事实的来源" aria-label="Permalink to &quot;六、官方文档应成为易变事实的来源&quot;">​</a></h2><p>中文解读适合建立概念地图，项目文档适合记录本仓库规则，当前 CLI 帮助适合确认本机版本，OpenAI Docs 则负责产品能力、配置与安全边界。模型名称、价格、入口名称和实验功能发生变化时，应回到官方页面重新核验。</p><p><img src="'+d+'" alt="图 5：中文解读、官方文档、项目规则与运行证据的事实层级"></p><h2 id="七、结语" tabindex="-1">七、结语 <a class="header-anchor" href="#七、结语" aria-label="Permalink to &quot;七、结语&quot;">​</a></h2><p>理解 Codex 的关键，不是记住所有按钮，而是看清模型、上下文、工具、权限与验证如何构成执行系统。只要这张图稳定，入口更新、模型更替和功能扩展都只是系统中的局部变化。</p><p><img src="'+s+'" alt="图 6：目标经过受控执行最终形成可审查交付"></p><h2 id="八、官方参考资料" tabindex="-1">八、官方参考资料 <a class="header-anchor" href="#八、官方参考资料" aria-label="Permalink to &quot;八、官方参考资料&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/codex" target="_blank" rel="noreferrer">OpenAI Docs：Codex</a></p><p><a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">OpenAI Docs：Pricing</a></p>',53)])])}const C=a(h,[["render",p]]);export{q as __pageData,C as default};
